CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE TYPE job_status AS ENUM ('queued','processing','completed','failed','cancelled');
CREATE TYPE subscription_status AS ENUM ('trialing','active','past_due','canceled','incomplete');
CREATE TABLE IF NOT EXISTS users (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), email text UNIQUE NOT NULL, password_hash text NOT NULL, name text NOT NULL, email_verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS workspaces (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), owner_user_id uuid NOT NULL REFERENCES users(id), name text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS workspace_members (workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE, user_id uuid REFERENCES users(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'member', created_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(workspace_id,user_id));
CREATE TABLE IF NOT EXISTS projects (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, created_by uuid NOT NULL REFERENCES users(id), name text NOT NULL, platform text NOT NULL DEFAULT 'youtube', status text NOT NULL DEFAULT 'draft', score integer, document jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS project_versions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, version_no integer NOT NULL, document jsonb NOT NULL, created_by uuid NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(project_id,version_no));
CREATE TABLE IF NOT EXISTS assets (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, uploaded_by uuid NOT NULL REFERENCES users(id), object_key text UNIQUE NOT NULL, original_name text NOT NULL, mime_type text NOT NULL, byte_size bigint NOT NULL, width integer, height integer, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS project_assets (project_id uuid REFERENCES projects(id) ON DELETE CASCADE, asset_id uuid REFERENCES assets(id) ON DELETE CASCADE, role text NOT NULL DEFAULT 'source', PRIMARY KEY(project_id,asset_id));
CREATE TABLE IF NOT EXISTS templates (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid REFERENCES workspaces(id) ON DELETE CASCADE, name text NOT NULL, category text, document jsonb NOT NULL DEFAULT '{}'::jsonb, is_public boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS brand_profiles (workspace_id uuid PRIMARY KEY REFERENCES workspaces(id) ON DELETE CASCADE, profile jsonb NOT NULL DEFAULT '{}'::jsonb, updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS creator_memory (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, kind text NOT NULL, content jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), deleted_at timestamptz);
CREATE TABLE IF NOT EXISTS ai_jobs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id), workspace_id uuid NOT NULL REFERENCES workspaces(id), type text NOT NULL, status job_status NOT NULL DEFAULT 'queued', provider text, input jsonb NOT NULL DEFAULT '{}'::jsonb, output jsonb, error_code text, error_message text, credits_reserved integer NOT NULL DEFAULT 0, created_at timestamptz NOT NULL DEFAULT now(), started_at timestamptz, completed_at timestamptz);
CREATE TABLE IF NOT EXISTS ai_generations (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), job_id uuid NOT NULL REFERENCES ai_jobs(id) ON DELETE CASCADE, project_id uuid REFERENCES projects(id) ON DELETE SET NULL, provider text NOT NULL, model text, prompt text, output jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS thumbnail_scores (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), project_id uuid NOT NULL REFERENCES projects(id) ON DELETE CASCADE, overall_score integer NOT NULL, category_scores jsonb NOT NULL, warnings jsonb NOT NULL DEFAULT '[]'::jsonb, recommendations jsonb NOT NULL DEFAULT '[]'::jsonb, confidence text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS experiments (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, project_id uuid REFERENCES projects(id) ON DELETE SET NULL, name text NOT NULL, status text NOT NULL DEFAULT 'draft', starts_at timestamptz, ends_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS experiment_variants (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), experiment_id uuid NOT NULL REFERENCES experiments(id) ON DELETE CASCADE, project_id uuid REFERENCES projects(id) ON DELETE SET NULL, label text NOT NULL, metrics jsonb, sample_size integer NOT NULL DEFAULT 0);
CREATE TABLE IF NOT EXISTS analytics_snapshots (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, connected_account_id uuid, source text NOT NULL, period_start date NOT NULL, period_end date NOT NULL, metrics jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS connected_accounts (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, provider text NOT NULL, provider_account_id text, access_token_enc text, refresh_token_enc text, expires_at timestamptz, scopes text[], created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now(), UNIQUE(workspace_id,provider));
CREATE TABLE IF NOT EXISTS subscriptions (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid UNIQUE NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, provider text NOT NULL, customer_id text, subscription_id text UNIQUE, plan text NOT NULL DEFAULT 'free', status subscription_status NOT NULL DEFAULT 'trialing', current_period_end timestamptz, created_at timestamptz NOT NULL DEFAULT now(), updated_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS credit_ledger (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, user_id uuid NOT NULL REFERENCES users(id), amount integer NOT NULL, reason text NOT NULL, idempotency_key text UNIQUE NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS notifications (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES users(id) ON DELETE CASCADE, workspace_id uuid NOT NULL REFERENCES workspaces(id) ON DELETE CASCADE, type text NOT NULL, payload jsonb NOT NULL DEFAULT '{}'::jsonb, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS audit_logs (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES users(id) ON DELETE SET NULL, workspace_id uuid REFERENCES workspaces(id) ON DELETE SET NULL, action text NOT NULL, resource_type text, resource_id uuid, metadata jsonb NOT NULL DEFAULT '{}'::jsonb, created_at timestamptz NOT NULL DEFAULT now());
CREATE INDEX IF NOT EXISTS projects_workspace_updated_idx ON projects(workspace_id,updated_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS assets_workspace_created_idx ON assets(workspace_id,created_at DESC) WHERE deleted_at IS NULL;
CREATE INDEX IF NOT EXISTS jobs_workspace_status_idx ON ai_jobs(workspace_id,status,created_at);
CREATE INDEX IF NOT EXISTS audit_workspace_created_idx ON audit_logs(workspace_id,created_at DESC);
